// ══════════════════════════════════════════════════════════════════════════════
// AURORA CONSOLE LAYER — HP·MERIDIAN identity for the unified standalone.
// ◆ block-letter wordmark through a cyan→violet→gold truecolor gradient;
// ❖ section rules; ⟦ ⟧ diamond badges; braille ladder bars ⣀⣄⣤⣦⣶⣷⣿ on a
// slate ⣀ track; kv-rows; the interactive menu; the doctor probe.
// Console text stays English (report-plain), file headers stay Russian.
// ══════════════════════════════════════════════════════════════════════════════

static AURORA_MODE: AtomicU8 = AtomicU8::new(0);
const MODE_NONE: u8 = 0;
const MODE_TRUECOLOR: u8 = 1;
const MODE_ANSI16: u8 = 2;

fn aurora_probe() {
    // truecolor → ansi16 → none, honoring NO_COLOR / FORCE_COLOR / TTY.
    let mode = if env_nonempty("NO_COLOR") {
        MODE_NONE
    } else if env_nonempty("FORCE_COLOR") {
        MODE_TRUECOLOR
    } else if stdout_is_tty() && env::var("TERM").unwrap_or_default() != "dumb" {
        if env_nonempty("COLORTERM") {
            MODE_TRUECOLOR
        } else {
            MODE_ANSI16
        }
    } else {
        MODE_NONE
    };
    AURORA_MODE.store(mode, Ordering::Relaxed);
}

fn env_nonempty(k: &str) -> bool {
    match env::var_os(k) {
        Some(v) => !v.is_empty(),
        None => false,
    }
}

fn aurora_mode() -> u8 {
    AURORA_MODE.load(Ordering::Relaxed)
}

fn aurora_mode_name() -> &'static str {
    match aurora_mode() {
        MODE_TRUECOLOR => "truecolor",
        MODE_ANSI16 => "ansi16",
        _ => "none",
    }
}

fn rst() -> &'static str {
    if aurora_mode() != MODE_NONE {
        "\x1b[0m"
    } else {
        ""
    }
}

fn rgb(r: f64, g: f64, b: f64) -> String {
    if aurora_mode() == MODE_TRUECOLOR {
        let cl = |v: f64| v.round().clamp(0.0, 255.0) as i64;
        format!("\x1b[38;2;{};{};{}m", cl(r), cl(g), cl(b))
    } else {
        String::new()
    }
}

fn pal(key: &str) -> (f64, f64, f64) {
    match key {
        "fg" => (214.0, 226.0, 235.0),
        "dim" => (108.0, 124.0, 138.0),
        "ok" => (126.0, 231.0, 135.0),
        "warn" => (255.0, 199.0, 95.0),
        "bad" => (255.0, 107.0, 107.0),
        "gold" => (255.0, 215.0, 95.0),
        "vio" => (167.0, 130.0, 255.0),
        "cyan" => (97.0, 218.0, 251.0),
        "mint" => (125.0, 255.0, 212.0),
        "sky" => (143.0, 216.0, 255.0),
        "rose" => (255.0, 143.0, 196.0),
        _ => (214.0, 226.0, 235.0),
    }
}

/// AURORA palette key wrapper: fg dim ok warn bad gold vio cyan mint sky rose.
fn c(txt: &str, key: &str) -> String {
    if aurora_mode() == MODE_NONE {
        return txt.to_string();
    }
    let (r, g, b) = pal(key);
    rgb(r, g, b) + txt + rst()
}

/// cyan (97,218,251) → violet (167,130,255) → gold (255,215,95), t∈[0,1].
fn grad_rgb(t: f64) -> (f64, f64, f64) {
    let stops: [(f64, (f64, f64, f64)); 3] = [
        (0.0, (97.0, 218.0, 251.0)),
        (0.5, (167.0, 130.0, 255.0)),
        (1.0, (255.0, 215.0, 95.0)),
    ];
    let t = t.clamp(0.0, 1.0);
    for w in stops.windows(2) {
        let (t0, c0) = w[0];
        let (t1, c1) = w[1];
        if t <= t1 {
            let k = (t - t0) / (t1 - t0);
            return (
                c0.0 + k * (c1.0 - c0.0),
                c0.1 + k * (c1.1 - c0.1),
                c0.2 + k * (c1.2 - c0.2),
            );
        }
    }
    stops[2].1
}

/// Paint a plain row through the AURORA gradient column by column.
fn grad(txt: &str) -> String {
    if aurora_mode() == MODE_NONE {
        return txt.to_string();
    }
    let chars: Vec<char> = txt.chars().collect();
    let n = chars.len();
    let mut out = String::new();
    for (i, ch) in chars.iter().enumerate() {
        if *ch == ' ' {
            out.push(*ch);
            continue;
        }
        let t = if n <= 1 { 0.5 } else { (i as f64 + 0.5) / n as f64 };
        let (r, g, b) = grad_rgb(t);
        out.push_str(&rgb(r, g, b));
        out.push(*ch);
    }
    out.push_str(rst());
    out
}

