fn bigfont(ch: char) -> Option<&'static [&'static str; 6]> {
    Some(match ch {
        'A' => &_MR_BIGFONT_A,
        'B' => &_MR_BIGFONT_B,
        'C' => &_MR_BIGFONT_C,
        'D' => &_MR_BIGFONT_D,
        'E' => &_MR_BIGFONT_E,
        'H' => &_MR_BIGFONT_H,
        'I' => &_MR_BIGFONT_I,
        'L' => &_MR_BIGFONT_L,
        'M' => &_MR_BIGFONT_M,
        'N' => &_MR_BIGFONT_N,
        'O' => &_MR_BIGFONT_O,
        'P' => &_MR_BIGFONT_P,
        'R' => &_MR_BIGFONT_R,
        'S' => &_MR_BIGFONT_S,
        'T' => &_MR_BIGFONT_T,
        'U' => &_MR_BIGFONT_U,
        'V' => &_MR_BIGFONT_V,
        'W' => &_MR_BIGFONT_W,
        'X' => &_MR_BIGFONT_X,
        'Y' => &_MR_BIGFONT_Y,
        '·' => &_MR_BIGFONT_DOT,
        ' ' => &_MR_BIGFONT_SP,
        _ => return None,
    })
}

fn bigtext(word: &str) -> [String; 6] {
    let mut rows: [String; 6] =
        [String::new(), String::new(), String::new(), String::new(), String::new(), String::new()];
    for ch in word.chars() {
        if let Some(gl) = bigfont(ch) {
            for i in 0..6 {
                rows[i].push_str(gl[i]);
                rows[i].push(' ');
            }
        }
    }
    rows
}

/// ◆-badge chip: ⟦ TEXT ⟧ — plain text ⟦ TEXT ⟧ when color is off.
fn badge(txt: &str, key: &str) -> String {
    c("⟦ ", "dim") + &c(txt, key) + &c(" ⟧", "dim")
}

fn rule() -> String {
    c(&("─".repeat(3) + " ❖ " + &"─".repeat(71)), "vio")
}

/// Braille ladder ⣀⣄⣤⣦⣶⣷⣿ over a slate ⣀ track, gradient-filled.
fn bar_str(p: f64, width: usize) -> String {
    const LADDER: [char; 7] = ['⣀', '⣄', '⣤', '⣦', '⣶', '⣷', '⣿'];
    let p = p.clamp(0.0, 1.0);
    let wf = width as f64;
    let full = (p * wf).floor() as usize;
    let frac = p * wf - full as f64;
    let mut cells = String::new();
    for i in 0..width {
        if i < full {
            let k = (i + 1) as f64 / wf;
            let mut cell = String::new();
            if aurora_mode() != MODE_NONE {
                let (r, g, b) = grad_rgb(k);
                cell.push_str(&rgb(r, g, b));
            }
            cell.push('⣿');
            cell.push_str(rst());
            cells.push_str(&cell);
        } else if i == full && frac > 0.02 {
            let idx = ((frac * 7.0) as usize).min(6);
            cells.push_str(&c(&LADDER[idx].to_string(), "dim"));
        } else {
            cells.push_str(&c("⣀", "dim"));
        }
    }
    cells.push_str(&c(&format!(" {:>5.1}%", p * 100.0), "dim"));
    cells
}

fn bar_inline(p: f64) {
    print!("\r  {}\x1b[0K", bar_str(p, 28));
    let _ = io::stdout().flush();
}

fn bar_end() {
    print!("\r\x1b[0K");
    let _ = io::stdout().flush();
}

fn kv(k: &str, v: &str) -> String {
    let wlen = k.chars().count();
    let pad = ".".repeat(30usize.saturating_sub(wlen).max(2));
    c(&format!("  {} ", k), "fg") + &c(&pad, "dim") + " " + &c(v, "gold")
}

fn banner() {
    println!();
    for row in bigtext("AB·CLOUD") {
        println!("  {}", grad(&row));
    }
    println!("  {}", c(&"═".repeat(66), "dim"));
    println!("  {}", grad(&format!("◆ {} ◆", "MERIDIAN OBSERVATORY · UNIFIED STANDALONE")));
    println!("  {}", c("brand: AB·CLOUD · MERIDIAN OBSERVATORY UNIFIED STANDALONE", "dim"));
    println!("  {}", rule());
}

/// Environment probe: rustc, build kind, color mode, embedded payloads.
fn doctor() -> bool {
    println!();
    println!("  {}", c("◆ DOCTOR — environment probe", "vio"));
    println!("  {}", rule());
    let rustc_v: &str = option_env!("RUSTC_VERSION").unwrap_or(RUSTC_FALLBACK);
    let build_kind: &str = option_env!("AB_BUILD_KIND").unwrap_or("standalone rustc (no crates)");
    let zeros = load_zeros_embedded();
    let n_sec = {
        let g = load_golden_embedded();
        match &g {
            Json::Obj(v) => v.len(),
            _ => 0,
        }
    };
    let mut rows: Vec<(&str, String)> = Vec::new();
    rows.push(("rustc", rustc_v.to_string()));
    rows.push(("build", build_kind.to_string()));
    rows.push(("color mode", aurora_mode_name().to_string()));
    rows.push(("term", env::var("TERM").unwrap_or_else(|_| "?".to_string())));
    rows.push((
        "embedded blobs",
        format!("zeros50k ({} b) · golden ({} b)", ZEROS50K_B64.len(), GOLDEN_B64.len()),
    ));
    rows.push(("zeros50k", format!("{} values", zeros.len())));
    rows.push(("golden", format!("{} sections", n_sec)));
    let ok = zeros.len() > 0 && n_sec > 0;
    for (k, v) in &rows {
        println!("{}", kv(&format!("{:<14}", k), v));
    }
    let verdict = if ok { badge("SANE", "ok") } else { badge("UNHEALTHY", "bad") };
    println!("  verdict: {}", verdict);
    ok
}
// ═══ GOLDEN SELFTEST LAYER ═══

// ══════════════════════════════════════════════════════════════════════════════
// GOLDEN SELFTEST — kernel numerics 1:1 (MT19937, RMT table, tolerance map);
// the check loop drives a braille-ladder progress bar when run on a TTY.
// ══════════════════════════════════════════════════════════════════════════════

fn count_anchors(golden: &Json) -> usize {
    let mut n = 0;
    if let Json::Obj(sections) = golden {
        for (section, gsec) in sections {
            if section == "meta" || section == "grids" {
                continue;
            }
            if let Json::Obj(keys) = gsec {
                n += keys.len();
            }
        }
    }
    n
}

/// Runs the full golden check battery; sink receives one line per anchor.
/// Returns (n_ok, n_all).
fn golden_selftest<F>(zeta: &[f64], golden: &Json, mut sink: F) -> (usize, usize)
where
    F: FnMut(usize, usize, &str),
{
    let results = compute_all(zeta, golden);
    let tol: std::collections::BTreeMap<&str, (f64, f64)> = std::collections::BTreeMap::from([
        ("lambert_w", (1e-9, 0.0)), ("gram_point", (1e-9, 0.0)), ("bN", (1e-9, 0.0)),
        ("spacings", (1e-9, 0.0)), ("gue2_cdf", (1e-7, 0.0)), ("goe_cdf", (1e-9, 0.0)),
        ("gue2_pdf", (1e-9, 0.0)), ("gamma_p", (1e-7, 0.0)), ("chi2_cdf", (1e-7, 0.0)),
        ("ks_pvalue", (1e-9, 0.0)), ("ks_zeros", (1e-6, 0.0)), ("cvm_zeros", (1e-6, 0.0)),
        ("ad_zeros", (1e-6, 0.0)), ("chi2_zeros", (1e-6, 0.0)), ("rmean_zeros", (1e-9, 0.0)),
        ("S2", (1e-7, 1e-12)), ("D3", (1e-7, 1e-12)), ("K_zeros", (1e-6, 0.0)),
        ("h1_zeta", (1e-6, 0.0)), ("ham_L8_open_a05_clean", (1e-7, 1e-8)),
        ("ham_L8_open_a025_2vort", (1e-7, 1e-8)), ("ham_L10_torus_a02_clean", (1e-7, 1e-8)),
        ("byers_yang", (1e-6, 1e-10)), ("connes", (1e-5, 1e-8)), ("chiral", (1e-5, 1e-9)),
        ("dirac_flux", (1e-6, 1e-10)), ("unfold", (1e-8, 0.0)), ("linreg", (1e-8, 0.0)),
        ("aicc", (1e-8, 0.0)), ("wald", (1e-9, 0.0)), ("spearman", (1e-8, 0.0)),
        ("test11", (1e-6, 0.0)), ("mon_entropy", (1e-6, 1e-10)),
        ("topo_tee", (1e-6, 1e-10)), ("rh_metrics", (1e-7, 0.0)),
    ]);
    let (mut n_ok, mut n_all) = (0, 0);
    if let Json::Obj(sections) = golden {
        for (section, gsec) in sections {
            if section == "meta" || section == "grids" {
                continue;
            }
            let (rtol, atol) = tol.get(section.as_str()).copied().unwrap_or((1e-6, 0.0));
            if let Json::Obj(keys) = gsec {
                for (key, gv) in keys {
                    n_all += 1;
                    let g = gv.num();
                    let cv = results
                        .get(section)
                        .and_then(|s| s.0.get(key))
                        .copied()
                        .unwrap_or(f64::NAN);
                    let (err, ok) = if g == 0.0 && cv == 0.0 {
                        (0.0, true)
                    } else if g == 0.0 {
                        (cv.abs(), cv.abs() <= atol + rtol)
                    } else {
                        let e = (cv - g).abs() / g.abs();
                        (e, e <= rtol || (cv - g).abs() <= atol)
                    };
                    if ok {
                        n_ok += 1;
                    }
                    let line = format!(
                        " [{}] {:<28} {:<18} g={:<22.17} p={:<22.17} rel={:.2e}",
                        if ok { "PASS" } else { "FAIL" },
                        section, key, g, cv, err
                    );
                    sink(n_all, 0, &line);
                }
            }
        }
    }
    (n_ok, n_all)
}

/// Classic plain-text selftest block (REPORT.txt capture + console).
/// When `live_bar` is set, a braille-ladder progress bar redraws inline.
fn selftest_block(zeta: &[f64], golden: &Json, note: &str, live_bar: bool) -> (String, bool, usize, usize) {
    let total = count_anchors(golden).max(1);
    let mut out: Vec<String> = Vec::new();
    out.push("=".repeat(78));
    out.push("ABCLOUD UNIFIED STANDALONE — GOLDEN SELFTEST".to_string());
    out.push("=".repeat(78));
    let mut done = 0usize;
    let (n_ok, n_all) = golden_selftest(zeta, golden, |_a, _b, line| {
        out.push(line.to_string());
        if live_bar {
            done += 1;
            bar_inline(done as f64 / total as f64);
        }
    });
    if live_bar {
        bar_end();
    }
    out.push("-".repeat(78));
    out.push(format!(" RESULT: {}/{} checks passed", n_ok, n_all));
    out.push("=".repeat(78));
    let ok = n_ok == n_all;
    out.push(format!(
        "SELFTEST: {}",
        if ok {
            "PASS — Rust kernel matches the Julia golden references."
        } else {
            "FAIL"
        }
    ));
    out.push(format!("⟦ data: {} ⟧", note));
    (out.join("\n"), ok, n_ok, n_all)
}

fn cmd_selftest(zeta: &[f64], golden: &Json, note: &str) -> bool {
    println!();
    println!("  {}", c("❖ GOLDEN SELFTEST — ABCLOUD UNIFIED STANDALONE (rust)", "vio"));
    println!("  {}", rule());
    let (text, ok, _, _) = selftest_block(zeta, golden, note, stdout_is_tty());
    println!("{}", text);
    ok
}
