/// Write aurora_report.html for an AbRun; returns the path.
fn write_html(run: &AbRun, verdict: &str, score: f64, vcolor: &str) -> String {
    let mut rows_html = String::new();
    for (k, v) in &run.metrics {
        rows_html.push_str(&format!(
            "<div class=\"chip\"><span class=\"k\">{}</span><span class=\"v\">{}</span></div>",
            html_escape(k),
            html_escape(v)
        ));
    }
    let mut secs_html = String::new();
    for (name, text) in &run.sections {
        secs_html.push_str(&format!(
            "<details open><summary>❖ {}</summary><pre>{}</pre></details>",
            html_escape(name),
            html_escape(text)
        ));
    }
    let doc = AURORA_HTML_TPL
        .replace("__SCORE__R", &format!("{:.1}", score * 100.0))
        .replace("__VCOLOR__", vcolor)
        .replace("__VERDICT__", &html_escape(verdict))
        .replace("__CHIPS__", &rows_html)
        .replace("__SECTIONS__", &secs_html)
        .replace("__BRAND__", &html_escape(AB_BRAND))
        .replace("__STAMP__", &html_escape(&run.stamp));
    let p = format!("{}/aurora_report.html", run.dir);
    let _ = fs::write(&p, &doc);
    p
}

/// The full AURORA report package: selftest + zeros battery + bN sweep +
/// metrics + txt/md/html, into results/run_<stamp>_report/.
fn report_cmd(data_opt: &str, golden_opt: &str) {
    let t0 = SystemTime::now();
    let (zeta, znote) = resolve_zeros(data_opt);
    let (golden, gnote) = resolve_golden(golden_opt);
    let mut run = AbRun::new("report");
    run.metric("n_zeros", zeta.len().to_string());

    // 1. golden selftest (199 anchors)
    let note = format!("{} · {}", znote, gnote);
    let (st_text, st_ok, n_ok, n_all) = selftest_block(&zeta, &golden, &note, false);
    let result_line = st_text
        .lines()
        .find(|l| l.contains("RESULT:"))
        .unwrap_or("see section")
        .trim()
        .to_string();
    run.add_section("GOLDEN SELFTEST (199 anchors)", st_text);
    run.metric("selftest", result_line);

    // 2. zeros battery
    run.add_section("ZERO-ANALYSIS BATTERY", zeros_battery_text(&zeta));
    let sp = normalized_spacings(&zeta);
    let mean_sp = sp.iter().sum::<f64>() / sp.len().max(1) as f64;
    let mut rmt = RmtTable::new();
    let (d_ks, p_ks) = ks_test(&mut rmt, &sp);
    let (r_mean, _nr) = mean_adjacent_spacing_ratio(&zeta);
    run.metric("gamma1", format!("{:.9}", zeta[0]));
    run.metric("gammaN", format!("{:.9}", zeta[zeta.len() - 1]));
    run.metric("mean_spacing", format!("{:.9}", mean_sp));
    run.metric("ks_D", format!("{:.6}", d_ks));
    run.metric("ks_p", format!("{:.6e}", p_ks));
    run.metric("r_mean", format!("{:.6}", r_mean));

    // 3. bN ladder sweep
    run.add_section("bN LADDER SWEEP", sweep_text(&zeta, &[]));

    // 4. write the package
    let p_txt = run.write_report_txt();
    let p_md = run.write_report_md();
    let score = if n_all > 0 { n_ok as f64 / n_all as f64 } else { 0.0 };
    let vcolor = if st_ok { "#7ee787" } else { "#ff6b6b" };
    let p_html = write_html(&run, &format!("{}/{}", n_ok, n_all), score, vcolor);

    let dt = SystemTime::now().duration_since(t0).unwrap_or_default().as_secs_f64();
    println!();
    println!("  {}", c("◆ REPORT PACKAGE COMPLETE", "vio"));
    println!("{}", kv("dir", &run.dir));
    println!("{}", kv("REPORT.txt", &p_txt));
    println!("{}", kv("final_report.md", &p_md));
    println!("{}", kv("aurora_report.html", &p_html));
    println!("{}", kv("elapsed", &format!("{:.1}s", dt)));
    println!("  {}", rule());
}
// ═══ CLI + INTERACTIVE MENU ═══

// ══════════════════════════════════════════════════════════════════════════════
// CLI + INTERACTIVE MENU — AURORA menu loop with the braille bar, honest
// doctor, and the full report package entry. Existing port commands (suite,
// ham, test11, hp, ...) are mapped onto the unified dispatcher 1:1.
// ══════════════════════════════════════════════════════════════════════════════

const AB_MENU: &str = "
  ◆ MAIN MENU — AB·CLOUD MERIDIAN UNIFIED STANDALONE
  ──────────────────────────────────────────────────────────────
   1) golden selftest        (199 anchors, bit-exact parity)
   2) zero-analysis battery  (spacings / KS / CvM / AD / S2 / D3)
   3) bN ladder sweep        (Berry conjugacy probe)
   4) full report package    (txt + md + html)
   5) doctor                 (environment probe)
   0) banner                 (wordmark + identity)
   q) quit
";

const AB_USAGE: &str = "usage: abcloud_unified <command> [options]

commands:
  menu                          interactive AURORA menu (default)
  selftest                      golden parity check (199 anchors)
  suite                         portable test suite subset
  zeros [--n N]                 zero-analysis battery
  bN [--N n...] [--offset k]    b(N) statistic
  gram [--n n...]               Gram points
  sweep                         b(N) ladder sweep
  test11 [--mc M] [--seed S]    Anderson-Darling honest MC
  hp                            H1 primary detector
  ham                           Monumental tier metrics
  report                        full report package (txt/md/html)
  plots                         600-dpi PNG battery (3 charts)
  doctor                        environment probe
  banner                        AURORA wordmark
  version                       print version
  help                          this text

options:
  --data PATH    zeros text file (default: embedded zeros50k, 50000 values)
  --golden PATH  golden JSON file (default: embedded golden, 37 sections)
  --n N / --N n  values for zeros/bN/gram (repeatable)
  --offset k     Gram offset for bN
  --mc M --seed S  Monte-Carlo draws / seed for test11
";

struct Args {
    cmd: String,
    data: String,
    golden: String,
    ns: Vec<i64>,
    offset: i64,
    mc: usize,
    seed: u32,
}

fn parse_args() -> Args {
    let argv: Vec<String> = env::args().skip(1).collect();
    let mut a = Args {
        cmd: argv.first().cloned().unwrap_or_else(|| "menu".to_string()),
        data: String::new(),
        golden: String::new(),
        ns: Vec::new(),
        offset: 0,
        mc: 200,
        seed: 777,
    };
    let mut i = 1usize;
    while i < argv.len() {
        match argv[i].as_str() {
            "--data" => {
                i += 1;
                a.data = argv.get(i).cloned().unwrap_or_default();
            }
            "--golden" => {
                i += 1;
                a.golden = argv.get(i).cloned().unwrap_or_default();
            }
            "--N" | "--n" => {
                i += 1;
                while i < argv.len() && !argv[i].starts_with('-') {
                    a.ns.push(argv[i].parse().unwrap_or(0));
                    i += 1;
                }
                i -= 1;
            }
            "--offset" => {
                i += 1;
                a.offset = argv.get(i).and_then(|v| v.parse().ok()).unwrap_or(0);
            }
            "--mc" => {
                i += 1;
                a.mc = argv.get(i).and_then(|v| v.parse().ok()).unwrap_or(200);
            }
            "--seed" => {
                i += 1;
                a.seed = argv.get(i).and_then(|v| v.parse().ok()).unwrap_or(777);
            }
            _ => {}
        }
        i += 1;
    }
    a
}

fn ab_print_section(title: &str) {
    println!();
    println!("  {}", c(&format!("❖ {}", title), "vio"));
    println!("  {}", c(&"─".repeat(74), "dim"));
}

/// Zero-analysis battery — kernel output of the port's `zeros` command 1:1.
fn zeros_battery_lines(z: &[f64]) -> Vec<String> {
    let mut out = Vec::new();
    let sp = normalized_spacings(z);
    let mut rmt = RmtTable::new();
    let mean = sp.iter().sum::<f64>() / sp.len() as f64;
    let var = sp.iter().map(|s| (s - mean) * (s - mean)).sum::<f64>() / (sp.len() - 1) as f64;
    let (d, p) = ks_test(&mut rmt, &sp);
    out.push(format!("zeros: n={}  g1={:.6}  gN={:.6}", z.len(), z[0], z[z.len() - 1]));
    out.push(format!("spacings: n={}  mean={:.6}  var={:.6}", sp.len(), mean, var));
    out.push(format!("KS  : D={:.6}  p={:.6e}", d, p));
    out.push(format!("CvM : W2={:.6}", cvm_test(&mut rmt, &sp)));
    out.push(format!("A2  : {:.6}", anderson_darling_stat(&mut rmt, &sp)));
    let (chi2, df, pchi) = chi2_gue_test(&mut rmt, &sp, 30);
    out.push(format!("chi2: {:.4}  df={}  p={:.6e}", chi2, df, pchi));
    let (r, n_r) = mean_adjacent_spacing_ratio(z);
    out.push(format!("<r> : {:.6}  (n_r={})", r, n_r));
    let pos = unfolded_positions(z);
    let mut rng = Mt19937::new(777);
    for l in [5.0f64, 10.0, 20.0, 50.0, 100.0] {
        out.push(format!("S2(L={:6.1}) = {:.6}", l, number_variance(&pos, l, 3000, &mut rng)));
    }
    for l in [5.0f64, 10.0, 20.0, 50.0] {
        out.push(format!("D3(L={:6.1}) = {:.6}", l, delta3_rigidity(&pos, l, 300, 300, &mut rng)));
    }
    out
}

fn zeros_battery_text(z: &[f64]) -> String {
    zeros_battery_lines(z).join("\n")
}

fn cmd_zeros(z: &[f64], n: i64) {
    let z = if n > 0 && (n as usize) < z.len() { &z[..n as usize] } else { z };
    ab_print_section(&format!("ZERO-ANALYSIS BATTERY (n = {})", z.len()));
    for l in zeros_battery_lines(z) {
        println!("{}", l);
    }
    println!("  {}", rule());
}

fn sweep_lines(z: &[f64], ns: &[i64]) -> Vec<String> {
    let ladder: Vec<i64> = if ns.is_empty() {
        vec![100, 500, 1000, 5000, 10000, 50000]
    } else {
        ns.to_vec()
    };
    let mut out = vec!["  N        b(N)".to_string()];
    for n in ladder {
        out.push(format!("{:6}  {:.8}", n, compute_bn(z, n, 0)));
    }
    out
}

fn sweep_text(z: &[f64], ns: &[i64]) -> String {
    sweep_lines(z, ns).join("\n")
}

fn cmd_sweep(z: &[f64], ns: &[i64]) {
    ab_print_section("bN LADDER SWEEP");
    for l in sweep_lines(z, ns) {
        println!("{}", l);
    }
    println!("  {}", rule());
}

#[allow(non_snake_case)]
fn cmd_bN(z: &[f64], ns: &[i64], offset: i64) {
    let ns: Vec<i64> = if ns.is_empty() { vec![100, 1000, 10000] } else { ns.to_vec() };
    for n in ns {
        println!("b(N={:6}, offset={}) = {:.10}", n, offset, compute_bn(z, n, offset));
    }
}

fn cmd_gram(ns: &[i64]) {
    let ns: Vec<i64> = if ns.is_empty() { vec![1, 10, 100] } else { ns.to_vec() };
    for n in ns {
        println!("g_{} = {:.10}", n, gram_point(n));
    }
}

fn cmd_test11(z: &[f64], mc: usize, seed: u32) {
    let sp = normalized_spacings(z);
    let mut rmt = RmtTable::new();
    let a2 = anderson_darling_stat(&mut rmt, &sp);
    println!("Test 11 (honest): exact A2 on n={} spacings: {:.6}", sp.len(), a2);
    if mc > 0 {
        let mut rng = Mt19937::new(seed);
        let mut buf = vec![0.0; sp.len()];
        let mut count = 0;
        for _ in 0..mc {
            rmt.sample(&mut rng, &mut buf);
            if anderson_darling_stat(&mut rmt, &buf) >= a2 {
                count += 1;
            }
        }
        println!(
            "MC null ({} draws): p = {:.6}  ({}/{} >= A2)",
            mc, (count + 1) as f64 / (mc + 1) as f64, count, mc
        );
    }
}

fn cmd_hp(z: &[f64]) {
    let n = z.len();
    let om: Vec<f64> = (0..726).map(|k| 0.3 + 0.004 * k as f64).collect();
    let w: Vec<f64> = (0..n)
        .map(|i| 0.5 * (1.0 - (2.0 * PI * i as f64 / (n - 1).max(1) as f64).cos()))
        .collect();
    let sw2: f64 = w.iter().map(|x| x * x).sum();
    let mut p = vec![0.0; om.len()];
    for (fi, omv) in om.iter().enumerate() {
        let (mut re, mut im) = (0.0, 0.0);
        for i in 0..n {
            re += w[i] * (omv * z[i]).cos();
            im -= w[i] * (omv * z[i]).sin();
        }
        p[fi] = (re * re + im * im) / sw2;
    }
    let mut ps = p.clone();
    ps.sort_by(|a, b| a.partial_cmp(b).unwrap());
    let med = 0.5 * (ps[ps.len() / 2 - 1] + ps[ps.len() / 2]);
    println!("H1 primary detector on {} positions:", n);
    let mut hits = 0;
    for pr in [2i64, 3, 5, 7, 11, 13] {
        let tgt = (pr as f64).ln();
        let best = om
            .iter()
            .enumerate()
            .min_by(|(_, a), (_, b)| (**a - tgt).abs().partial_cmp(&(**b - tgt).abs()).unwrap())
            .map(|(i, _)| i)
            .unwrap();
        let snr = p[best] / med;
        if snr >= 10.0 {
            hits += 1;
        }
        println!("  SNR(log {:2}) = {:.6e}  [{}]", pr, snr, if snr >= 10.0 { "PEAK" } else { "-" });
    }
    println!("  verdict: {}/6 prime harmonics above SNR 10", hits);
}

fn cmd_ham() {
    let scns: Vec<(&str, AbCloudConfig, usize)> = vec![
        ("L8_open_a025_2vort", AbCloudConfig::new(8, 8,
            vec![Vortex{x:3.5,y:3.5,q:1.0},Vortex{x:6.5,y:6.5,q:-1.0}],
            0.25, 1.0, "open", 0.0).with(96, "monumental"), 8),
        ("L10_open_a03_clean", AbCloudConfig::new(10, 10, vec![],
            0.3, 1.0, "open", 0.0).with(96, "monumental"), 10),
        ("L12_open_a03_clean", AbCloudConfig::new(12, 12, vec![],
            0.3, 1.0, "open", 0.0).with(96, "monumental"), 12),
    ];
    for (sname, cfg, l) in scns {
        let t = ham_tier_compute(&cfg, l);
        println!("{}  (L={}, N={})", sname, l, cfg.nx * cfg.ny);
        for c in 0..3usize {
            println!(
                "  c{}: S(f=0.25)={:.9}  S(f=0.5)={:.9}  S(f=0.75)={:.9}  IPR={:.9}",
                c, t.s[c * 3], t.s[c * 3 + 1], t.s[c * 3 + 2], t.ipr[c]);
        }
        println!(
            "  TEE: slope={:.9}  gamma_top={:.9}  S_mean(f=0.5)={:.9}  S_std(f=0.5)={:.9}",
            t.slope, t.gamma_top, t.s_mean[MON_TEE_IDX[1]], t.s_std[MON_TEE_IDX[1]]);
        let mut rmt2 = RmtTable::new();
        let cb = central_band_eigs(&t.ev, 0.6);
        let (dks, pks) = rh_band_ks(&mut rmt2, &cb);
        let (r, ncb) = mean_adjacent_spacing_ratio(&cb);
        println!(
            "  RH metrics (central 0.6): n={}  D={:.6}  p={:.4e}  <r>={:.6}",
            ncb, dks, pks, r);
    }
}

fn cmd_plots(data_opt: &str) {
    let (zeta, _) = resolve_zeros(data_opt);
    let (stamp, _) = now_timespec();
    let pdir = format!("results/plots_{}", stamp);
    match plots_run(&pdir, &zeta) {
        Ok(paths) => {
            ab_print_section("PNG BATTERY (600 dpi, 3600×2250)");
            for p in &paths {
                println!("{}", kv("wrote", p));
            }
            println!("  {}", rule());
        }
        Err(e) => {
            eprintln!("ERROR: plots failed: {}", e);
            exit(2);
        }
    }
}

fn menu() -> i32 {
    banner();
    loop {
        println!("{}", AB_MENU);
        print!("  select ❖ ");
        let _ = io::stdout().flush();
        let mut line = String::new();
        if io::stdin().read_line(&mut line).unwrap_or(0) == 0 {
            println!();
            return 0;
        }
        let ch = line.trim().to_lowercase();
        match ch.as_str() {
            "1" => {
                let zeta = load_zeros_embedded();
                let golden = load_golden_embedded();
                cmd_selftest(&zeta, &golden, &format!(
                    "embedded zeros50k ({} values) · embedded golden", zeta.len()));
            }
            "2" => {
                let zeta = load_zeros_embedded();
                cmd_zeros(&zeta, 0);
            }
            "3" => {
                let zeta = load_zeros_embedded();
                cmd_sweep(&zeta, &[]);
            }
            "4" => {
                report_cmd("", "");
            }
            "5" => {
                doctor();
            }
            "0" => {
                banner();
            }
            "q" | "quit" | "exit" => {
                println!("  {}", c("◆ until the next meridian — goodbye", "vio"));
                return 0;
            }
            other => {
                println!("  {}", c(&format!("unknown choice: {:?}", other), "warn"));
            }
        }
    }
}

fn main() {
    aurora_probe();
    let args = parse_args();
    let code = match args.cmd.as_str() {
        "menu" => menu(),
        "banner" => {
            banner();
            0
        }
        "version" => {
            println!("{} {}", AB_BRAND, AB_VERSION);
            0
        }
        "help" | "-h" | "--help" => {
            print!("{}", AB_USAGE);
            0
        }
        "doctor" => {
            if doctor() { 0 } else { 1 }
        }
        "selftest" => {
            let (zeta, znote) = resolve_zeros(&args.data);
            let (golden, gnote) = resolve_golden(&args.golden);
            let note = format!("{} · {}", znote, gnote);
            if cmd_selftest(&zeta, &golden, &note) { 0 } else { 1 }
        }
        "suite" => {
            let (zeta, _) = resolve_zeros(&args.data);
            run_suite(&zeta);
            0
        }
        "zeros" => {
            let (zeta, _) = resolve_zeros(&args.data);
            let n = args.ns.first().copied().unwrap_or(0);
            cmd_zeros(&zeta, n);
            0
        }
        "bN" => {
            let (zeta, _) = resolve_zeros(&args.data);
            cmd_bN(&zeta, &args.ns, args.offset);
            0
        }
        "gram" => {
            cmd_gram(&args.ns);
            0
        }
        "sweep" => {
            let (zeta, _) = resolve_zeros(&args.data);
            cmd_sweep(&zeta, &args.ns);
            0
        }
        "test11" => {
            let (zeta, _) = resolve_zeros(&args.data);
            cmd_test11(&zeta, args.mc, args.seed);
            0
        }
        "hp" => {
            let (zeta, _) = resolve_zeros(&args.data);
            cmd_hp(&zeta);
            0
        }
        "ham" => {
            cmd_ham();
            0
        }
        "report" => {
            report_cmd(&args.data, &args.golden);
            0
        }
        "plots" => {
            cmd_plots(&args.data);
            0
        }
        other => {
            eprintln!("unknown command: {}\n\n{}", other, AB_USAGE);
            2
        }
    };
    exit(code);
}
